from test.support.os_helper import TESTFN, unlink

def _t():
    from operator import countOf
    assert countOf([1, 2, 2, 3, 2, 5], 2) == 3, ('assertEqual', countOf([1, 2, 2, 3, 2, 5], 2), 3)
    assert countOf((1, 2, 2, 3, 2, 5), 2) == 3, ('assertEqual', countOf((1, 2, 2, 3, 2, 5), 2), 3)
    assert countOf('122325', '2') == 3, ('assertEqual', countOf('122325', '2'), 3)
    assert countOf('122325', '6') == 0, ('assertEqual', countOf('122325', '6'), 0)
    try:
        countOf(*(42, 1))
    except TypeError:
        pass
    try:
        countOf(*(countOf, countOf))
    except TypeError:
        pass
    d = {'one': 3, 'two': 3, 'three': 3, 1j: 2j}
    for k in d:
        assert countOf(d, k) == 1, ('assertEqual', countOf(d, k), 1)
    assert countOf(d.values(), 3) == 3, ('assertEqual', countOf(d.values(), 3), 3)
    assert countOf(d.values(), 2j) == 1, ('assertEqual', countOf(d.values(), 2j), 1)
    assert countOf(d.values(), 1j) == 0, ('assertEqual', countOf(d.values(), 1j), 0)
    f = open(TESTFN, 'w', encoding='utf-8')
    try:
        f.write('a\nb\nc\nb\n')
    finally:
        f.close()
    f = open(TESTFN, 'r', encoding='utf-8')
    try:
        for letter, count in (('a', 1), ('b', 2), ('c', 1), ('d', 0)):
            f.seek(0, 0)
            assert countOf(f, letter + '\n') == count, ('assertEqual', countOf(f, letter + '\n'), count)
    finally:
        f.close()
        try:
            unlink(TESTFN)
        except OSError:
            pass
